mapper.select:
SELECT id, session_id AS sessionId, class_code AS classCode, type, status, reason, target_session_date AS targetSessionDate, target_start_time AS targetStartTime, target_end_time AS targetEndTime, target_location AS targetLocation, applicant_id AS applicantId, reviewer_id AS reviewerId, review_note AS reviewNote, reviewed_at AS reviewedAt, created_at AS createdAt, updated_at AS updatedAt FROM attendance_work_order WHERE 1=1
AND class_code = #{classCode}
AND status = #{status}
ORDER BY created_at DESC
